with zero API costs.", "starter_code": "# Module 0: Chai Dhaba Fast Sentiment & Bill Analyzer\nfrom transformers import pipeline\nfrom datasets import load_dataset\n\n# 1. Load tiny 260MB model (< 15 seconds on CPU/T4)\nclassifier = pipeline(\"sentiment-analysis\", model=\"distilbert/distilbert-base-uncased-finetuned-sst-2-english\")\n\n# 2. Stream 3 customer reviews from HF datasets\ndataset = load_dataset(\"rotten_tomatoes\", split=\"test\", streaming=True)\nsample_reviews = [item[\"text\"] for item in dataset.take(3)]\n\n# 3. Analyze Dhaba Customer Orders & Feedback\ncustomer_orders = [\n    {\"customer\": \"Aslam\", \"item\": \"Doodh Patti & Paratha\", \"review\": \"The tea was scalding hot, perfectly sweet, and the paratha was delightfully crisp!\"},\n    {\"customer\": \"Bilal\", \"item\": \"Karak Chai\", \"review\": \"Cold tea, way too much sugar, and stale biscuits. Terrible service.\"}\n]\n\nprint(\"--- Dhaba Customer Feedback Analysis ---\")\nfor order in customer_orders:\n    result = classifier(order[\"review\"])[0]\n    print(f\"Customer: {order[''customer'']} ({order[''item'']})\")\n    print(f\"Feedback: {order[''review'']}\")\n    print(f\"Sentiment: {result[''label'']} (Confidence: {result[''score'']:.4f})\\n\")\n", "runnable_starter_code": "# Module 0: Chai Dhaba Fast Sentiment & Bill Analyzer\nfrom transformers import pipeline\nfrom datasets import load_dataset\n\n# 1. Load tiny 260MB model (< 15 seconds on CPU/T4)\nclassifier = pipeline(\"sentiment-analysis\", model=\"distilbert/distilbert-base-uncased-finetuned-sst-2-english\")\n\n# 2. Stream 3 customer reviews from HF datasets\ndataset = load_dataset(\"rotten_tomatoes\", split=\"test\", streaming=True)\nsample_reviews = [item[\"text\"] for item in dataset.take(3)]\n\n# 3. Analyze Dhaba Customer Orders & Feedback\ncustomer_orders = [\n    {\"customer\": \"Aslam\", \"item\": \"Doodh Patti & Paratha\", \"review\": \"The tea was scalding hot, perfectly sweet, and the paratha was delightfully crisp!\"},\n    {\"customer\": \"Bilal\", \"item\": \"Karak Chai\", \"review\": \"Cold tea, way too much sugar, and stale biscuits. Terrible service.\"}\n]\n\nprint(\"--- Dhaba Customer Feedback Analysis ---\")\nfor order in customer_orders:\n    result = classifier(order[\"review\"])[0]\n    print(f\"Customer: {order[''customer'']} ({order[''item'']})\")\n    print(f\"Feedback: {order[''review'']}\")\n    print(f\"Sentiment: {result[''label'']} (Confidence: {result[''score'']:.4f})\\n\")\n", "gradio_code": "import gradio as gr\nfrom transformers import pipeline\n\nclf = pipeline(\"sentiment-analysis\", model=\"distilbert/distilbert-base-uncased-finetuned-sst-2-english\")\n\ndef analyze_review(customer_name, review_text):\n    res = clf(review_text)[0]\n    emoji = \"[POSITIVE] Zabardast!\" if res[\"label\"] == \"POSITIVE\" else \"\u26a0\ufe0f Shikayat (Negative)!\"\n    return f\"{emoji} Score: {res[''score'']:.2%}\"\n\ndemo = gr.Interface(\n    fn=analyze_review,\n    inputs=[gr.Textbox(label=\"Customer Name\", value=\"Hamza\"), gr.Textbox(label=\"Dhaba Feedback\", value=\"Best Doodh Patti in town!\")],\n    outputs=gr.Textbox(label=\"AI Sentiment Verdict\"),\n    title=\"Chai Dhaba Sentiment Munshi\"\n)\ndemo.launch()\n", "gradio_demo_code": "import gradio as gr\nfrom transformers import pipeline\n\nclf = pipeline(\"sentiment-analysis\", model=\"distilbert/distilbert-base-uncased-finetuned-sst-2-english\")\n\ndef analyze_review(customer_name, review_text):\n    res = clf(review_text)[0]\n    emoji = \"[POSITIVE] Zabardast!\" if res[\"label\"] == \"POSITIVE\" else \"\u26a0\ufe0f Shikayat (Negative)!\"\n    return f\"{emoji} Score: {res[''score'']:.2%}\"\n\ndemo = gr.Interface(\n    fn=analyze_review,\n    inputs=[gr.Textbox(label=\"Customer Name\", value=\"Hamza\"), gr.Textbox(label=\"Dhaba Feedback\", value=\"Best Doodh Patti in town!\")],\n    outputs=gr.Textbox(label=\"AI Sentiment Verdict\"),\n    title=\"Chai Dhaba Sentiment Munshi\"\n)\ndemo.launch()\n"}}'::jsonb,
