rter_code": "# Module 2: Chain-of-Thought (CoT) Prompting with SmolLM2-360M\nimport torch\nfrom transformers import pipeline\n\n# 1. Load HF''s modern open-weight SmolLM2-360M-Instruct\npipe = pipeline(\"text-generation\", model=\"HuggingFaceTB/SmolLM2-360M-Instruct\", torch_dtype=torch.float32)\n\n# 2. Format chat with System Persona and Step-by-Step Chain-of-Thought\nmessages = [\n    {\"role\": \"system\", \"content\": \"You are a witty, analytical Pakistani Rishta Matchmaker auntie. Think step-by-step and provide a compatibility score (0-100%) in clean JSON.\"},\n    {\"role\": \"user\", \"content\": \"Candidate 1: Software Engineer, introverted, loves biryani and gaming at 2 AM.\\nCandidate 2: Clinical Doctor, extroverted, loves hiking, hates fast food.\\nAre they compatible?\"}\n]\n\n# 3. Generate response with controlled temperature\nprompt = pipe.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)\noutputs = pipe(prompt, max_new_tokens=220, temperature=0.6, do_sample=True, top_p=0.9)\ngenerated_text = outputs[0][\"generated_text\"][len(prompt):]\n\nprint(\"=== SmolLM2 Rishta Matchmaker CoT Output ===\")\nprint(generated_text.strip())\n", "runnable_starter_code": "# Module 2: Chain-of-Thought (CoT) Prompting with SmolLM2-360M\nimport torch\nfrom transformers import pipeline\n\n# 1. Load HF''s modern open-weight SmolLM2-360M-Instruct\npipe = pipeline(\"text-generation\", model=\"HuggingFaceTB/SmolLM2-360M-Instruct\", torch_dtype=torch.float32)\n\n# 2. Format chat with System Persona and Step-by-Step Chain-of-Thought\nmessages = [\n    {\"role\": \"system\", \"content\": \"You are a witty, analytical Pakistani Rishta Matchmaker auntie. Think step-by-step and provide a compatibility score (0-100%) in clean JSON.\"},\n    {\"role\": \"user\", \"content\": \"Candidate 1: Software Engineer, introverted, loves biryani and gaming at 2 AM.\\nCandidate 2: Clinical Doctor, extroverted, loves hiking, hates fast food.\\nAre they compatible?\"}\n]\n\n# 3. Generate response with controlled temperature\nprompt = pipe.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)\noutputs = pipe(prompt, max_new_tokens=220, temperature=0.6, do_sample=True, top_p=0.9)\ngenerated_text = outputs[0][\"generated_text\"][len(prompt):]\n\nprint(\"=== SmolLM2 Rishta Matchmaker CoT Output ===\")\nprint(generated_text.strip())\n", "gradio_code": "import gradio as gr\nfrom transformers import pipeline\n\npipe = pipeline(\"text-generation\", model=\"HuggingFaceTB/SmolLM2-360M-Instruct\")\n\ndef evaluate_prompt(system_prompt, user_query, temp):\n    chat = [{\"role\": \"system\", \"content\": system_prompt}, {\"role\": \"user\", \"content\": user_query}]\n    prompt = pipe.tokenizer.apply_chat_template(chat, tokenize=False, add_generation_prompt=True)\n    out = pipe(prompt, max_new_tokens=180, temperature=float(temp), do_sample=temp > 0.0)\n    return out[0][\"generated_text\"][len(prompt):].strip()\n\ndemo = gr.Interface(\n    fn=evaluate_prompt,\n    inputs=[gr.Textbox(label=\"System Persona\", value=\"You are a strict code reviewer.\"), gr.Textbox(label=\"User Prompt\", value=\"Why is O(N^2) bad in production?\"), gr.Slider(0.1, 1.2, value=0.7, label=\"Temperature\")],\n    outputs=gr.Textbox(label=\"SmolLM2 Response\", lines=6),\n    title=\"SmolLM2 Interactive Prompt Engineering Lab\"\n)\ndemo.launch()\n", "gradio_demo_code": "import gradio as gr\nfrom transformers import pipeline\n\npipe = pipeline(\"text-generation\", model=\"HuggingFaceTB/SmolLM2-360M-Instruct\")\n\ndef evaluate_prompt(system_prompt, user_query, temp):\n    chat = [{\"role\": \"system\", \"content\": system_prompt}, {\"role\": \"user\", \"content\": user_query}]\n    prompt = pipe.tokenizer.apply_chat_template(chat, tokenize=False, add_generation_prompt=True)\n    out = pipe(prompt, max_new_tokens=180, temperature=float(temp), do_sample=temp > 0.0)\n    return out[0][\"generated_text\"][len(prompt):].strip()\n\ndemo = gr.Interface(\n    fn=evaluate_prompt,\n    inputs=[gr.Textbox(label=\"System Persona\", value=\"You are a strict code reviewer.\"), gr.Textbox(label=\"User Prompt\", value=\"Why is O(N^2) bad in production?\"), gr.Slider(0.1, 1.2, value=0.7, label=\"Temperature\")],\n    outputs=gr.Textbox(label=\"SmolLM2 Response\", lines=6),\n    title=\"SmolLM2 Interactive Prompt Engineering Lab\"\n)\ndemo.launch()\n"}}'::jsonb,
