  '[{"title": "PyTorch Official Deep Learning Tutorials", "url": "https://pytorch.org/tutorials/"}, {"title": "Andrej Karpathy: Micrograd Video Series", "url": "https://www.youtube.com/watch?v=VMj-3S1tku0"}]'::jsonb,
  '@preset midnight
@animate flow
flow LR: Module 4 PyTorch Deep Learning Graph
  tensors[PyTorch Tensors on CUDA GPU] $database -> autograd[Dynamic Autograd Graph] $brain
  autograd -> forward[Forward Pass & SwiGLU Activations] $layers
  forward -> amp[Mixed Precision AMP & GradScaler] $cpu
  amp -> opt[AdamW Parameter Update] $server *',
  'midnight',
  'flow',
  'transformer-expert',
  'Mini-Autograd Deep Learning Engine & Multi-GPU Training Loop',
  '{"platform": "Google Colab Free Tier (Nvidia T4 15GB VRAM)", "vram_required": "2 GB VRAM", "estimated_cost": "$0.00 Free", "compute_units_tip": "PyTorch MLP and CNN training loops take less than 2 minutes on Colab T4 GPU; zero compute credits required.", "one_click_command": "python -c \"import torch; print(torch.cuda.is_available())\""}'::jsonb,
  '{"title": "Desi Meme Classifier & Sarcastic Roast Bot", "urdu_title": "Meme Classifier & Roast Engine", "description": "PyTorch se custom convolutional/MLP neural network train karein jo viral memes ko detect kare (e.g. ''Sarfaraz Dhoka Nahi Dega'' vs ''Disappointed Pakistani Fan'') aur instant humorous roast dialogue generate kare.", "colab_url": "https://colab.research.google.com/drive/1ai_ustaad_mod4_meme_roast_bot", "checklist": ["Custom PyTorch Dataset & DataLoader", "CrossEntropyLoss with AdamW & CosineAnnealing", "Mixed Precision (AMP) training on Free Colab T4", "Model checkpointing and inference visualizer"], "xp_reward": 200, "badge_name": "meme-roaster", "hf_subproject": {"module_number": 4, "module_slug": "deep-learning-and-pytorch-foundations", "project_title": "PyTorch Autograd & MLP Sentiment Classifier from Scratch", "project_slug": "pytorch-autograd-mlp-sentiment", "hf_model": "distilbert/distilbert-base-uncased", "hf_model_url": "https://huggingface.co/distilbert/distilbert-base-uncased", "hf_dataset": "rotten_tomatoes", "hf_dataset_url": "https://huggingface.co/datasets/rotten_tomatoes", "colab_url": "https://colab.research.google.com/github/isaim0011/ai-mastery-notebooks/blob/main/module_04_pytorch_mlp_classifier.ipynb", "colab_notebook_url": "https://colab.research.google.com/github/isaim0011/ai-mastery-notebooks/blob/main/module_04_pytorch_mlp_classifier.ipynb", "kaggle_url": "https://www.kaggle.com/code/isaim0011/module-04-pytorch-autograd-mlp", "kaggle_notebook_url": "https://www.kaggle.com/code/isaim0011/module-04-pytorch-autograd-mlp", "hardware_requirement": "Free Colab CPU / T4 GPU (0.5 GB VRAM)", "estimated_runtime_seconds": "< 15s tokenization + 5-epoch training loop", "key_learning_takeaway": "Building custom PyTorch nn.Module architectures from scratch, tensor batching, autograd backpropagation, AdamW parameter updates, and loss curve convergence.", "starter_code": "# Module 4: Custom PyTorch Neural Network MLP trained on HF Dataset\nimport torch\nimport torch.nn as nn\nfrom datasets import load_dataset\nfrom transformers import AutoTokenizer\n\n# 1. Load Tokenizer & Stream Dataset\ntokenizer = AutoTokenizer.from_pretrained(\"distilbert/distilbert-base-uncased\")\ndataset = load_dataset(\"rotten_tomatoes\", split=\"train\", streaming=True)\nbatch = list(dataset.take(200))\n\n# 2. Tokenize inputs into PyTorch Tensors\nencodings = tokenizer([b[\"text\"] for b in batch], padding=True, truncation=True, max_length=64, return_tensors=\"pt\")\nlabels = torch.tensor([b[\"label\"] for b in batch], dtype=torch.long)\n\n# 3. Define 3-Layer Deep Neural Network with PyTorch nn.Module\nclass SentimentMLP(nn.Module):\n    def __init__(self, vocab_size=30522, embed_dim=32, hidden_dim=64):\n        super().__init__()\n        self.embedding = nn.Embedding(vocab_size, embed_dim)\n        self.fc1 = nn.Linear(embed_dim, hidden_dim)\n        self.relu = nn.ReLU()\n        self.dropout = nn.Dropout(0.2)\n        self.fc2 = nn.Linear(hidden_dim, 2)\n    def forward(self, input_ids):\n        x = self.embedding(input_ids).mean(dim=1)\n        return self.fc2(self.dropout(self.relu(self.fc1(x))))\n\nmodel = SentimentMLP()\noptimizer = torch.optim.AdamW(model.parameters(), lr=0.01)\ncriterion = nn.CrossEntropyLoss()\n\n# 4. Run 5 Training Epochs with PyTorch Autograd\nfor epoch in range(5):\n    optimizer.zero_grad()\n    logits = model(encodings[\"input_ids\"])\n    loss = criterion(logits, labels)\n    loss.backward()\n    optimizer.step()\n    acc = (logits.argmax(dim=1) == labels).float().mean()\n    print(f\"Epoch {epoch+1}/5 | CrossEntropy Loss: {loss.item():.4f} | Batch Accuracy: {acc*100:.1f}%\")\n", "runnable_starter_code": "# Module 4: Custom PyTorch Neural Network MLP trained on HF Dataset\nimport torch\nimport torch.nn as nn\nfrom datasets import load_dataset\nfrom transformers import AutoTokenizer\n\n# 1. Load Tokenizer & Stream Dataset\ntokenizer = AutoTokenizer.from_pretrained(\"distilbert/distilbert-base-uncased\")\ndataset = load_dataset(\"rotten_tomatoes\", split=\"train\", streaming=True)\nbatch = list(dataset.take(200))\n\n# 2. Tokenize inputs into PyTorch Tensors\nencodings = tokenizer([b[\"text\"] for b in batch], padding=True, truncation=True, max_length=64, return_tensors=\"pt\")\nlabels = torch.tensor([b[\"label\"] for b in batch], dtype=torch.long)\n\n# 3. Define 3-Layer Deep Neural Network with PyTorch nn.Module\nclass SentimentMLP(nn.Module):\n    def __init__(self, vocab_size=30522, embed_dim=32, hidden_dim=64):\n        super().__init__()\n        self.embedding = nn.Embedding(vocab_size, embed_dim)\n        self.fc1 = nn.Linear(embed_dim, hidden_dim)\n        self.relu = nn.ReLU()\n        self.dropout = nn.Dropout(0.2)\n        self.fc2 = nn.Linear(hidden_dim, 2)\n    def forward(self, input_ids):\n        x = self.embedding(input_ids).mean(dim=1)\n        return self.fc2(self.dropout(self.relu(self.fc1(x))))\n\nmodel = SentimentMLP()\noptimizer = torch.optim.AdamW(model.parameters(), lr=0.01)\ncriterion = nn.CrossEntropyLoss()\n\n# 4. Run 5 Training Epochs with PyTorch Autograd\nfor epoch in range(5):\n    optimizer.zero_grad()\n    logits = model(encodings[\"input_ids\"])\n    loss = criterion(logits, labels)\n    loss.backward()\n    optimizer.step()\n    acc = (logits.argmax(dim=1) == labels).float().mean()\n    print(f\"Epoch {epoch+1}/5 | CrossEntropy Loss: {loss.item():.4f} | Batch Accuracy: {acc*100:.1f}%\")\n", "gradio_code": "import gradio as gr, torch, torch.nn as nn\nfrom transformers import AutoTokenizer\n\ntok = AutoTokenizer.from_pretrained(\"distilbert/distilbert-base-uncased\")\nclass MLP(nn.Module):\n    def __init__(self): super().__init__(); self.emb = nn.Embedding(30522, 32); self.fc = nn.Linear(32, 2)\n    def forward(self, x): return self.fc(self.emb(x).mean(dim=1))\nnet = MLP().eval()\n\ndef predict_sentiment(text):\n    ids = tok(text, return_tensors=\"pt\")[\"input_ids\"]\n    with torch.no_grad():\n        probs = torch.softmax(net(ids), dim=-1)[0]\n    return {\"Negative\": float(probs[0]), \"Positive\": float(probs[1])}\n\ndemo = gr.Interface(fn=predict_sentiment, inputs=gr.Textbox(value=\"This movie was pure cinematic poetry!\"), outputs=gr.Label(), title=\"PyTorch Custom Neural Network Classifier\")\ndemo.launch()\n", "gradio_demo_code": "import gradio as gr, torch, torch.nn as nn\nfrom transformers import AutoTokenizer\n\ntok = AutoTokenizer.from_pretrained(\"distilbert/distilbert-base-uncased\")\nclass MLP(nn.Module):\n    def __init__(self): super().__init__(); self.emb = nn.Embedding(30522, 32); self.fc = nn.Linear(32, 2)\n    def forward(self, x): return self.fc(self.emb(x).mean(dim=1))\nnet = MLP().eval()\n\ndef predict_sentiment(text):\n    ids = tok(text, return_tensors=\"pt\")[\"input_ids\"]\n    with torch.no_grad():\n        probs = torch.softmax(net(ids), dim=-1)[0]\n    return {\"Negative\": float(probs[0]), \"Positive\": float(probs[1])}\n\ndemo = gr.Interface(fn=predict_sentiment, inputs=gr.Textbox(value=\"This movie was pure cinematic poetry!\"), outputs=gr.Label(), title=\"PyTorch Custom Neural Network Classifier\")\ndemo.launch()\n"}}'::jsonb,
  4
