  node_a[Leaf Node A (Weight)] $code -> mul[Multiply Op] $cpu
  node_b[Leaf Node B (Input)] $code -> mul
  mul -> add[Add Op (Bias)] $layers
  add -> loss[Loss Value] $brain
  loss -> topo_back[Reverse Topological Backward Pass] $terminal *',
