from dataclasses import dataclass

@dataclass(slots=True)
class DhabaItem:
    name: str
    price: float

def compute_bill(items: list[DhabaItem], discount_pct: float = 0.0) -> float:
    subtotal = sum(i.price for i in items)
    discounted = subtotal * (1.0 - (discount_pct / 100.0))
