\"\"\"
    return modelfile_str.strip()

def query_local_ollama_stream(prompt: str, model_name: str = "llama3.1:8b") -> Generator[str, None, None]:
    \"\"\"Streams tokens from local Ollama REST endpoint (http://localhost:11434/api/generate).\"\"\"
    payload = json.dumps({
